#include "darc_internal.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {char st;DarcFlatEnt*o,*n;uint64_t reused,newbytes;double reuse;} DiffEnt;
typedef struct {DiffEnt*v;size_t n,cap;uint64_t add,del,mod,meta,type,hard;int64_t logical_delta;uint64_t reused_bytes,new_bytes;} DiffSet;
static int family(uint8_t t){return (t==1||t==4)?1:t==2?2:t==3?3:0;}
static bool pref(const char*p,const char*f){if(!f||!*f)return true;size_t n=strlen(f),pn=strlen(p);return pn>=n&&!memcmp(p,f,n)&&(p[n]==0||p[n]=='/');}
static int de_push(DiffSet*d,DiffEnt e){if(d->n==d->cap){size_t nc=d->cap?d->cap*2:128;DiffEnt*x=darc_realloc(d->v,nc*sizeof*x);if(!x)return -1;d->v=x;d->cap=nc;}d->v[d->n++]=e;return 0;}
static int file_load(const char*repo,const DarcCid*c,DarcFileObj*f){DarcObject o;int rc=darc_object_load(repo,c,&o,1);if(rc)return rc;if(o.type!=OBJ_FILE||darc_file_parse(o.payload.data,o.payload.len,f)){darc_object_free(&o);return DARC_E_CORRUPT;}darc_object_free(&o);return 0;}
static int chunk_reuse(const char*repo,const DarcCid*oc,const DarcCid*nc,uint64_t*reuse,uint64_t*newb){*reuse=*newb=0;DarcFileObj a,b;int rc=file_load(repo,oc,&a);if(rc)return rc;rc=file_load(repo,nc,&b);if(rc){darc_file_free(&a);return rc;}bool*used=darc_calloc(a.chunk_n?a.chunk_n:1,sizeof*used);if(!used){darc_file_free(&a);darc_file_free(&b);return DARC_E_IO;}for(size_t j=0;j<b.chunk_n;j++){bool hit=false;for(size_t i=0;i<a.chunk_n;i++)if(!used[i]&&a.chunks[i].len==b.chunks[j].len&&darc_cid_eq(&a.chunks[i].cid,&b.chunks[j].cid)){used[i]=true;hit=true;break;}if(hit)*reuse+=b.chunks[j].len;else *newb+=b.chunks[j].len;}free(used);darc_file_free(&a);darc_file_free(&b);return 0;}
static int build_diff(const char*repo,DarcFlatTree*a,DarcFlatTree*b,const char*filter,DiffSet*d){memset(d,0,sizeof*d);size_t i=0,j=0;while(i<a->n||j<b->n){DarcFlatEnt*oe=i<a->n?&a->v[i]:NULL,*ne=j<b->n?&b->v[j]:NULL;int c;if(!oe)c=1;else if(!ne)c=-1;else c=strcmp(oe->path,ne->path);const char*path=c<=0&&oe?oe->path:ne->path;if(!pref(path,filter)){if(c<=0&&oe)i++;if(c>=0&&ne)j++;continue;}DiffEnt e;memset(&e,0,sizeof e);if(c<0){e.st='D';e.o=oe;d->del++;if(family(oe->type)==1)d->logical_delta-=(int64_t)oe->logical_size;i++;}else if(c>0){e.st='A';e.n=ne;d->add++;if(family(ne->type)==1)d->logical_delta+=(int64_t)ne->logical_size;j++;}else{e.o=oe;e.n=ne;int fo=family(oe->type),fn=family(ne->type);if(fo!=fn){e.st='T';d->type++;if(fo==1)d->logical_delta-=(int64_t)oe->logical_size;if(fn==1)d->logical_delta+=(int64_t)ne->logical_size;}else if(fo==1){if(oe->logical_size!=ne->logical_size||memcmp(oe->file_digest,ne->file_digest,32)){e.st='M';d->mod++;d->logical_delta+=(int64_t)ne->logical_size-(int64_t)oe->logical_size;int rc=chunk_reuse(repo,&oe->cid,&ne->cid,&e.reused,&e.newbytes);if(rc)return rc;e.reuse=ne->logical_size?100.0*(double)e.reused/(double)ne->logical_size:0.0;d->reused_bytes+=e.reused;d->new_bytes+=e.newbytes;}else {bool h=oe->type!=ne->type||oe->hardlink_group!=ne->hardlink_group||oe->target_len!=ne->target_len||(oe->target_len&&memcmp(oe->target,ne->target,oe->target_len));bool m=oe->mode!=ne->mode||oe->mtime_ns!=ne->mtime_ns;if(h){e.st='H';d->hard++;}else if(m){e.st='P';d->meta++;}}}else if(fo==3){bool m=oe->mode!=ne->mode||oe->mtime_ns!=ne->mtime_ns||oe->target_len!=ne->target_len||(oe->target_len&&memcmp(oe->target,ne->target,oe->target_len));if(m){e.st='P';d->meta++;}}else if(fo==2){if(oe->mode!=ne->mode||oe->mtime_ns!=ne->mtime_ns){e.st='P';d->meta++;}}if(e.st&&de_push(d,e))return DARC_E_IO;i++;j++;continue;}if(de_push(d,e))return DARC_E_IO;}return 0;}
static void json_path(const char*p){char*disp=darc_display_bytes((const uint8_t*)p,strlen(p));char*e=darc_json_escape_bytes((const uint8_t*)disp,strlen(disp));printf("\"path\":%s",e);free(e);free(disp);if(!darc_valid_utf8((const uint8_t*)p,strlen(p))){printf(",\"path_hex\":\"");for(size_t i=0;i<strlen(p);i++)printf("%02x",(unsigned char)p[i]);printf("\"");}}
static const char*etype(uint8_t t){return t==1?"file":t==2?"directory":t==3?"symlink":t==4?"hardlink":"unknown";}
static void json_entry_fields(const DiffEnt*e){const char*p=e->n?e->n->path:e->o->path;printf("\"status\":\"%c\",",e->st);json_path(p);printf(",\"old_type\":");if(e->o)printf("\"%s\"",etype(e->o->type));else printf("null");printf(",\"new_type\":");if(e->n)printf("\"%s\"",etype(e->n->type));else printf("null");if(e->o&&family(e->o->type)==1)printf(",\"old_size\":%llu",(unsigned long long)e->o->logical_size);if(e->n&&family(e->n->type)==1)printf(",\"new_size\":%llu",(unsigned long long)e->n->logical_size);if(e->st=='M')printf(",\"reused_chunk_bytes\":%llu,\"new_chunk_bytes\":%llu,\"reuse_percent\":%.3f",(unsigned long long)e->reused,(unsigned long long)e->newbytes,e->reuse);if(e->o&&e->n){printf(",\"metadata_changed\":[");int first=1;if(e->o->mode!=e->n->mode){printf("\"mode\"");first=0;}if(e->o->mtime_ns!=e->n->mtime_ns){printf("%s\"mtime_ns\"",first?"":",");first=0;}if(e->o->type!=e->n->type||e->o->hardlink_group!=e->n->hardlink_group){printf("%s\"hardlink_topology\"",first?"":",");first=0;}if(e->o->target_len!=e->n->target_len||(e->o->target_len&&memcmp(e->o->target,e->n->target,e->o->target_len)))printf("%s\"symlink_target\"",first?"":",");printf("]");}}
static void json_entry(const DiffEnt*e){putchar('{');json_entry_fields(e);putchar('}');}
static void svg(const char*aid,const char*bid,const DiffSet*d,int topn){size_t rows=d->n<(size_t)topn?d->n:(size_t)topn;size_t h=260+rows*24+40;printf("<svg xmlns=\"http://www.w3.org/2000/svg\" version=\"1.1\" width=\"1100\" height=\"%zu\" viewBox=\"0 0 1100 %zu\">\n",h,h);printf("<rect width=\"1100\" height=\"%zu\" fill=\"white\"/><text x=\"32\" y=\"42\" font-family=\"sans-serif\" font-size=\"24\">DARC diff %.12s → %.12s</text>\n",h,aid,bid);printf("<text x=\"32\" y=\"82\" font-family=\"monospace\" font-size=\"16\">A %llu   D %llu   M %llu   P %llu   T %llu   H %llu   logical %+lld bytes</text>\n",(unsigned long long)d->add,(unsigned long long)d->del,(unsigned long long)d->mod,(unsigned long long)d->meta,(unsigned long long)d->type,(unsigned long long)d->hard,(long long)d->logical_delta);uint64_t den=d->reused_bytes+d->new_bytes;double pct=den?100.0*(double)d->reused_bytes/(double)den:100.0;printf("<text x=\"32\" y=\"112\" font-family=\"sans-serif\" font-size=\"15\">Modified-file chunk reuse %.2f%%</text><rect x=\"32\" y=\"128\" width=\"700\" height=\"18\" fill=\"#ddd\"/><rect x=\"32\" y=\"128\" width=\"%.2f\" height=\"18\" fill=\"#4a8\"/>\n",pct,7.0*pct);printf("<text x=\"32\" y=\"184\" font-family=\"monospace\" font-size=\"15\">ST   OLD SIZE      NEW SIZE      REUSE    PATH</text>\n");for(size_t i=0;i<rows;i++){const DiffEnt*e=&d->v[i];const char*p=e->n?e->n->path:e->o->path;char*x=darc_xml_escape((const uint8_t*)p,strlen(p));unsigned long long os=e->o&&family(e->o->type)==1?(unsigned long long)e->o->logical_size:0,ns=e->n&&family(e->n->type)==1?(unsigned long long)e->n->logical_size:0;printf("<text x=\"32\" y=\"%zu\" font-family=\"monospace\" font-size=\"14\">%c   %12llu  %12llu  %6.1f%%  %s</text>\n",214+i*24,e->st,os,ns,e->st=='M'?e->reuse:0.0,x?x:"");free(x);}if(rows<d->n)printf("<text x=\"32\" y=\"%zu\" font-family=\"sans-serif\" font-size=\"13\">Truncated: showing %zu of %zu changed paths.</text>\n",220+rows*24,rows,d->n);printf("</svg>\n");}
int darc_cmd_diff(const char*repo,const DarcConfig*c,const char*as,const char*bs){DarcCid ai,bi;DarcSnapshotObj a,b;int rc=darc_resolve_snapshot(repo,as,&ai,&a);if(rc)return rc;rc=darc_resolve_snapshot(repo,bs,&bi,&b);if(rc){darc_snapshot_free(&a);return rc;}DarcFlatTree at,bt;rc=darc_flatten_snapshot(repo,&a,&at);if(!rc)rc=darc_flatten_snapshot(repo,&b,&bt);if(rc){darc_snapshot_free(&a);darc_snapshot_free(&b);darc_flat_free(&at);darc_flat_free(&bt);return rc;}DiffSet d;rc=build_diff(repo,&at,&bt,c->diff_path,&d);if(rc)goto done;char ah[65],bh[65];darc_cid_hex(&ai,ah);darc_cid_hex(&bi,bh);if(c->output_format==3)svg(ah,bh,&d,c->top_n_svg);else if(c->output_format==1){printf("{\"old_snapshot\":\"%s\",\"new_snapshot\":\"%s\",\"summary\":{\"added\":%llu,\"deleted\":%llu,\"modified\":%llu,\"metadata_only\":%llu,\"type_changed\":%llu,\"hardlink_changed\":%llu,\"logical_delta\":%lld,\"reused_chunk_bytes\":%llu,\"new_chunk_bytes\":%llu},\"entries\":[",ah,bh,(unsigned long long)d.add,(unsigned long long)d.del,(unsigned long long)d.mod,(unsigned long long)d.meta,(unsigned long long)d.type,(unsigned long long)d.hard,(long long)d.logical_delta,(unsigned long long)d.reused_bytes,(unsigned long long)d.new_bytes);for(size_t i=0;i<d.n;i++){if(i)putchar(',');json_entry(&d.v[i]);}printf("]}\n");}else if(c->output_format==2){for(size_t i=0;i<d.n;i++){printf("{\"record\":\"entry\",");json_entry_fields(&d.v[i]);printf("}\n");}printf("{\"record\":\"summary\",\"added\":%llu,\"deleted\":%llu,\"modified\":%llu,\"metadata_only\":%llu,\"type_changed\":%llu,\"hardlink_changed\":%llu,\"logical_delta\":%lld}\n",(unsigned long long)d.add,(unsigned long long)d.del,(unsigned long long)d.mod,(unsigned long long)d.meta,(unsigned long long)d.type,(unsigned long long)d.hard,(long long)d.logical_delta);}else{uint64_t den=d.reused_bytes+d.new_bytes;double pct=den?100.0*(double)d.reused_bytes/(double)den:100.0;printf("Summary: +%llu  -%llu  M%llu  P%llu  T%llu  H%llu    logical %+lld bytes    chunk reuse %.1f%%\n\nST  OLD SIZE      NEW SIZE      REUSE    PATH\n",(unsigned long long)d.add,(unsigned long long)d.del,(unsigned long long)d.mod,(unsigned long long)d.meta,(unsigned long long)d.type,(unsigned long long)d.hard,(long long)d.logical_delta,pct);for(size_t i=0;i<d.n;i++){DiffEnt*e=&d.v[i];const char*p=e->n?e->n->path:e->o->path;char*disp=darc_display_bytes((const uint8_t*)p,strlen(p));if(e->st=='M')printf("%c   %12llu  %12llu  %6.1f%%   %s\n",e->st,(unsigned long long)e->o->logical_size,(unsigned long long)e->n->logical_size,e->reuse,disp);else printf("%c   %12llu  %12llu     -     %s\n",e->st,(unsigned long long)(e->o&&family(e->o->type)==1?e->o->logical_size:0),(unsigned long long)(e->n&&family(e->n->type)==1?e->n->logical_size:0),disp);free(disp);}}
done:free(d.v);darc_flat_free(&at);darc_flat_free(&bt);darc_snapshot_free(&a);darc_snapshot_free(&b);return rc;}
